choose.when:
(
e.created_by = #{scope.userId} OR e.primary_responsible_user_id = #{scope.userId} OR EXISTS ( SELECT 1 FROM system_user scoped_user WHERE scoped_user.tenant_id = e.tenant_id AND scoped_user.id = #{scope.userId} AND scoped_user.organization_id = e.organization_id AND scoped_user.status = 1 AND scoped_user.deleted = 0 ) OR EXISTS ( SELECT 1 FROM system_user_team_membership scoped_membership WHERE scoped_membership.tenant_id = e.tenant_id AND scoped_membership.user_id = #{scope.userId} AND scoped_membership.team_organization_id = e.organization_id AND scoped_membership.deleted = 0 ) OR EXISTS ( SELECT 1 FROM equipment_responsible_person scoped_person WHERE scoped_person.tenant_id = e.tenant_id AND scoped_person.equipment_id = e.id AND scoped_person.user_id = #{scope.userId} AND scoped_person.status = 1 AND scoped_person.deleted = 0 ) OR EXISTS ( SELECT 1 FROM inspection_task scoped_inspection WHERE scoped_inspection.tenant_id = e.tenant_id AND scoped_inspection.equipment_id = e.id AND scoped_inspection.deleted = 0 AND ( scoped_inspection.assignee_user_id = #{scope.userId} OR EXISTS ( SELECT 1 FROM inspection_task_assignee scoped_assignee WHERE scoped_assignee.tenant_id = scoped_inspection.tenant_id AND scoped_assignee.task_id = scoped_inspection.id AND scoped_assignee.user_id = #{scope.userId} AND scoped_assignee.deleted = 0 ) ) ) OR EXISTS ( SELECT 1 FROM maintenance_task scoped_maintenance WHERE scoped_maintenance.tenant_id = e.tenant_id AND scoped_maintenance.equipment_id = e.id AND scoped_maintenance.deleted = 0 AND ( scoped_maintenance.assignee_user_id = #{scope.userId} OR EXISTS ( SELECT 1 FROM maintenance_task_collaborator scoped_collaborator WHERE scoped_collaborator.tenant_id = scoped_maintenance.tenant_id AND scoped_collaborator.task_id = scoped_maintenance.id AND scoped_collaborator.user_id = #{scope.userId} ) ) )
OR
e.organization_id IN
#{organizationId}
)

mapper.select:
SELECT COALESCE(SUM(planned_date = CURRENT_DATE()), 0) AS due_today,
       COALESCE(SUM(task_status IN (
           'PENDING', 'IN_PROGRESS', 'OVERDUE'
       )), 0) AS pending,
       COALESCE(SUM(
           task_status = 'OVERDUE'
           OR (
               task_status NOT IN ('COMPLETED', 'CANCELLED', 'VOIDED')
               AND due_time < CURRENT_TIMESTAMP(3)
           )
       ), 0) AS overdue,
       COALESCE(SUM(
           task_status = 'COMPLETED'
           AND DATE(completed_time) = CURRENT_DATE()
       ), 0) AS completed_today
FROM inspection_task task
WHERE task.tenant_id = #{tenantId}
  AND task.deleted = 0
  AND (
      task.assignee_user_id = #{userId}
      OR EXISTS (
          SELECT 1
          FROM inspection_task_assignee assignee
          WHERE assignee.tenant_id = task.tenant_id
            AND assignee.task_id = task.id
            AND assignee.user_id = #{userId}
      )
  )

SELECT e.id, e.equipment_code, e.equipment_name, organization.organization_name, location.location_name, COALESCE(current_status.status_code, 'IDLE') AS current_status_code, responsible.real_name AS primary_responsible_name, barcode.access_token AS active_barcode_token FROM equipment e JOIN organization ON organization.tenant_id = e.tenant_id AND organization.id = e.organization_id AND organization.status = 1 AND organization.deleted = 0 LEFT JOIN location ON location.tenant_id = e.tenant_id AND location.id = e.location_id AND location.deleted = 0 LEFT JOIN system_user responsible ON responsible.tenant_id = e.tenant_id AND responsible.id = e.primary_responsible_user_id AND responsible.deleted = 0 LEFT JOIN equipment_current_status current_status ON current_status.tenant_id = e.tenant_id AND current_status.equipment_id = e.id LEFT JOIN equipment_barcode barcode ON barcode.tenant_id = e.tenant_id AND barcode.equipment_id = e.id AND barcode.active_slot = 1 WHERE e.tenant_id = #{tenantId} AND e.status = 1 AND e.deleted = 0 AND
AND COALESCE(current_status.status_code, 'IDLE') = #{currentStatusCode}
ORDER BY e.equipment_code, e.id LIMIT #{offset}, #{pageSize}

SELECT #{startDate} AS start_date,
       #{endDate} AS end_date,
       COUNT(*) AS due,
       COALESCE(SUM(task.task_status IN ('COMPLETED', 'PENDING_REVIEW')), 0) AS completed,
       COALESCE(SUM(task.task_status NOT IN (
           'COMPLETED', 'PENDING_REVIEW', 'CANCELLED', 'VOIDED'
       )), 0) AS pending,
       COALESCE(SUM(
           task.task_status = 'OVERDUE'
           OR (
               task.task_status NOT IN (
                   'COMPLETED', 'PENDING_REVIEW', 'CANCELLED', 'VOIDED'
               )
               AND task.due_time < CURRENT_TIMESTAMP(3)
           )
       ), 0) AS overdue,
       COALESCE(SUM(EXISTS (
           SELECT 1 FROM inspection_abnormal abnormal
           WHERE abnormal.tenant_id = task.tenant_id
             AND abnormal.task_id = task.id AND abnormal.deleted = 0
       )), 0) AS abnormal,
       COALESCE(SUM(task.source_type = 'PLAN'), 0) AS plan_due,
       COALESCE(SUM(task.source_type = 'PLAN'
           AND task.task_status IN ('COMPLETED', 'PENDING_REVIEW')), 0) AS plan_completed,
       COALESCE(SUM(task.source_type = 'PLAN' AND (
           task.task_status = 'OVERDUE'
           OR (task.task_status NOT IN ('COMPLETED', 'PENDING_REVIEW', 'CANCELLED', 'VOIDED')
               AND task.due_time < CURRENT_TIMESTAMP(3))
       )), 0) AS plan_overdue,
       COALESCE(SUM(task.task_status IN ('COMPLETED', 'PENDING_REVIEW')
           AND task.completed_time >= #{startTime}
           AND task.completed_time < #{endExclusive}), 0) AS registered,
       COALESCE(SUM(task.source_type = 'QUICK_ENTRY'
           AND task.task_status IN ('COMPLETED', 'PENDING_REVIEW')
           AND task.completed_time >= #{startTime}
           AND task.completed_time < #{endExclusive}), 0) AS quick_registered,
       COUNT(DISTINCT CASE
           WHEN task.task_status IN ('COMPLETED', 'PENDING_REVIEW')
            AND task.completed_time >= #{startTime}
            AND task.completed_time < #{endExclusive}
           THEN task.equipment_id END) AS equipment_covered
FROM inspection_task task
WHERE task.tenant_id = #{tenantId} AND task.deleted = 0
  AND task.task_status NOT IN ('CANCELLED', 'VOIDED')
  AND (
      task.planned_date BETWEEN #{startDate} AND #{endDate}
      OR (
          task.completed_time >= #{startTime}
          AND task.completed_time < #{endExclusive}
      )
  )
  AND (
      task.assignee_user_id = #{userId}
      OR EXISTS (
          SELECT 1 FROM inspection_task_assignee assignee
          WHERE assignee.tenant_id = task.tenant_id
            AND assignee.task_id = task.id
            AND assignee.user_id = #{userId}
      )
  )

mapper.sql:
WITH RECURSIVE selected_organization_tree AS ( SELECT id FROM organization WHERE tenant_id = #{tenantId} AND id = #{query.organizationId} AND deleted = 0 UNION ALL SELECT child.id FROM organization child JOIN selected_organization_tree parent ON child.parent_id = parent.id WHERE child.tenant_id = #{tenantId} AND child.deleted = 0 ), assessment_tasks AS ( SELECT task.id AS task_id, task.organization_id, organization.organization_name, COALESCE(task.submitted_by, task.assignee_user_id) AS attributed_user_id, attributed_user.real_name AS attributed_user_name, attributed_user.organization_id AS user_organization_id, user_organization.organization_name AS user_organization_name, CASE WHEN task.submitted_time IS NOT NULL THEN 1 ELSE 0 END AS completed_task, CASE WHEN task.submitted_time IS NOT NULL AND task.submitted_time <= task.due_time THEN 1 ELSE 0 END AS on_time_task, CASE WHEN task.submitted_time IS NOT NULL AND task.submitted_time > task.due_time THEN 1 ELSE 0 END AS late_task, CASE WHEN task.submitted_time IS NULL AND task.due_time >= CURRENT_TIMESTAMP(3) THEN 1 ELSE 0 END AS pending_task, CASE WHEN task.submitted_time IS NULL AND task.due_time < CURRENT_TIMESTAMP(3) THEN 1 ELSE 0 END AS overdue_task, CASE WHEN EXISTS ( SELECT 1 FROM inspection_abnormal abnormal WHERE abnormal.tenant_id = task.tenant_id AND abnormal.task_id = task.id AND abnormal.deleted = 0 ) THEN 1 ELSE 0 END AS abnormal_task FROM inspection_task task JOIN organization organization ON organization.tenant_id = task.tenant_id AND organization.id = task.organization_id AND organization.deleted = 0 LEFT JOIN system_user attributed_user ON attributed_user.tenant_id = task.tenant_id AND attributed_user.id = COALESCE(task.submitted_by, task.assignee_user_id) AND attributed_user.deleted = 0 LEFT JOIN organization user_organization ON user_organization.tenant_id = attributed_user.tenant_id AND user_organization.id = attributed_user.organization_id AND user_organization.deleted = 0 WHERE task.tenant_id = #{tenantId} AND task.deleted = 0 AND task.source_type = 'PLAN' AND task.task_status NOT IN ('CANCELLED', 'VOIDED') AND task.planned_date BETWEEN #{query.startDate} AND #{query.endDate} AND ()
AND task.organization_id IN (SELECT id FROM selected_organization_tree)
AND COALESCE(task.submitted_by, task.assignee_user_id) = #{query.userId}
)

mapper.select:
SELECT organization.id AS organization_id, organization.parent_id, organization.organization_code, organization.organization_name FROM organization WHERE organization.tenant_id = #{tenantId} AND organization.status = 1 AND organization.deleted = 0 AND (
1 = 1
organization.id IN
#{organizationId}
1 = 0
) ORDER BY organization.parent_id, organization.sort_order, organization.id

SELECT report_user.id AS user_id, report_user.organization_id, report_user.username, report_user.real_name FROM system_user report_user WHERE report_user.tenant_id = #{tenantId} AND report_user.organization_id IS NOT NULL AND report_user.status = 1 AND report_user.deleted = 0 AND (
1 = 1
( report_user.id = #{currentUserId} OR
report_user.organization_id IN
#{organizationId}
)
1 = 0
) ORDER BY report_user.real_name, report_user.id

mapper.sql:
WITH RECURSIVE selected_organization_tree AS ( SELECT id FROM organization WHERE tenant_id = #{tenantId} AND id = #{query.organizationId} AND deleted = 0 UNION ALL SELECT child.id FROM organization child JOIN selected_organization_tree parent ON child.parent_id = parent.id WHERE child.tenant_id = #{tenantId} AND child.deleted = 0 ), performance_detail_items AS ( SELECT task.id AS task_id, task.task_code, task.source_type, task.task_status, task.planned_date, task.due_time, task.submitted_time, task.organization_id, organization.organization_name, task.equipment_id, equipment.equipment_code, equipment.equipment_name, task.scheme_name_snapshot AS scheme_name, item.id AS task_item_id, item.item_code, item.item_name, result.result_status, result.result_code, COALESCE( result.text_value, result.selected_value, CAST(result.numeric_value AS CHAR), result.result_code ) AS result_value, COALESCE(task.submitted_by, task.assignee_user_id) AS attributed_user_id, attributed_user.real_name AS attributed_user_name, CASE WHEN task.source_type = 'QUICK_ENTRY' THEN 'QUICK' WHEN task.submitted_time IS NOT NULL AND task.submitted_time <= task.due_time THEN 'ON_TIME' WHEN task.submitted_time IS NOT NULL AND task.submitted_time > task.due_time THEN 'LATE' WHEN task.submitted_time IS NULL AND task.due_time < CURRENT_TIMESTAMP(3) THEN 'OVERDUE' ELSE 'PENDING' END AS timeliness, CASE WHEN abnormal.id IS NULL THEN FALSE ELSE TRUE END AS abnormal, abnormal.id AS abnormal_id, abnormal.abnormal_code, abnormal.abnormal_title, abnormal.abnormal_description, abnormal.abnormal_status FROM inspection_task task JOIN organization organization ON organization.tenant_id = task.tenant_id AND organization.id = task.organization_id AND organization.deleted = 0 JOIN equipment equipment ON equipment.tenant_id = task.tenant_id AND equipment.id = task.equipment_id AND equipment.deleted = 0 JOIN inspection_task_item item ON item.tenant_id = task.tenant_id AND item.task_id = task.id AND item.deleted = 0 LEFT JOIN inspection_task_result result ON result.tenant_id = item.tenant_id AND result.task_item_id = item.id AND result.deleted = 0 LEFT JOIN system_user attributed_user ON attributed_user.tenant_id = task.tenant_id AND attributed_user.id = COALESCE(task.submitted_by, task.assignee_user_id) AND attributed_user.deleted = 0 LEFT JOIN inspection_abnormal abnormal ON abnormal.tenant_id = item.tenant_id AND abnormal.task_item_id = item.id AND abnormal.deleted = 0 AND abnormal.id = ( SELECT MAX(latest_abnormal.id) FROM inspection_abnormal latest_abnormal WHERE latest_abnormal.tenant_id = item.tenant_id AND latest_abnormal.task_item_id = item.id AND latest_abnormal.deleted = 0 ) WHERE task.tenant_id = #{tenantId} AND task.deleted = 0 AND task.source_type IN ('PLAN', 'QUICK_ENTRY') AND task.task_status NOT IN ('CANCELLED', 'VOIDED') AND ( (task.source_type = 'PLAN' AND task.planned_date BETWEEN #{query.startDate} AND #{query.endDate}) OR (task.source_type = 'QUICK_ENTRY' AND task.submitted_time >= #{query.startDate} AND task.submitted_time < DATE_ADD(#{query.endDate}, INTERVAL 1 DAY)) ) AND ()
AND task.organization_id IN (SELECT id FROM selected_organization_tree)
AND COALESCE(task.submitted_by, task.assignee_user_id) = #{query.userId}
), performance_detail_tasks AS ( SELECT task_id, MAX(task_code) AS task_code, MAX(source_type) AS source_type, MAX(task_status) AS task_status, MAX(planned_date) AS planned_date, MAX(due_time) AS due_time, MAX(submitted_time) AS submitted_time, MAX(organization_id) AS organization_id, MAX(organization_name) AS organization_name, MAX(equipment_id) AS equipment_id, MAX(equipment_code) AS equipment_code, MAX(equipment_name) AS equipment_name, MAX(scheme_name) AS scheme_name, MAX(attributed_user_id) AS attributed_user_id, MAX(attributed_user_name) AS attributed_user_name, MAX(timeliness) AS timeliness, COUNT(*) AS item_count, COALESCE(SUM(CASE WHEN result_status = 'SUBMITTED' THEN 1 ELSE 0 END), 0) AS completed_item_count, COALESCE(SUM(CASE WHEN abnormal = TRUE THEN 1 ELSE 0 END), 0) AS abnormal_item_count, MAX(abnormal) AS abnormal FROM performance_detail_items GROUP BY task_id )

mapper.select:

SELECT COUNT(*)
FROM performance_detail_items
WHERE task_id = #{taskId}

WITH RECURSIVE selected_organization_tree AS ( SELECT id FROM organization WHERE tenant_id = #{tenantId} AND id = #{query.organizationId} AND deleted = 0 UNION ALL SELECT child.id FROM organization child JOIN selected_organization_tree parent ON child.parent_id = parent.id WHERE child.tenant_id = #{tenantId} AND child.deleted = 0 ) SELECT COUNT(DISTINCT task.id) AS completed_task_count, COUNT(DISTINCT CASE WHEN result.result_status = 'SUBMITTED' THEN item.id END) AS completed_item_count, COUNT(DISTINCT task.equipment_id) AS equipment_covered, COUNT(DISTINCT CASE WHEN abnormal.id IS NOT NULL THEN task.id END) AS abnormal_task_count FROM inspection_task task LEFT JOIN inspection_task_item item ON item.tenant_id = task.tenant_id AND item.task_id = task.id AND item.deleted = 0 LEFT JOIN inspection_task_result result ON result.tenant_id = item.tenant_id AND result.task_item_id = item.id AND result.deleted = 0 LEFT JOIN inspection_abnormal abnormal ON abnormal.tenant_id = item.tenant_id AND abnormal.task_item_id = item.id AND abnormal.deleted = 0 WHERE task.tenant_id = #{tenantId} AND task.deleted = 0 AND task.source_type = 'QUICK_ENTRY' AND task.task_status NOT IN ('CANCELLED', 'VOIDED') AND task.submitted_time >= #{query.startDate} AND task.submitted_time < DATE_ADD(#{query.endDate}, INTERVAL 1 DAY) AND ()
AND task.organization_id IN (SELECT id FROM selected_organization_tree)
AND task.submitted_by = #{query.userId}

SELECT COALESCE(SUM(planned_date = CURRENT_DATE()), 0) AS due_today,
       COALESCE(SUM(task_status IN (
           'PENDING', 'IN_PROGRESS', 'PAUSED',
           'PENDING_CONFIRMATION', 'OVERDUE'
       )), 0) AS pending,
       COALESCE(SUM(
           task_status = 'OVERDUE'
           OR (
               task_status NOT IN ('COMPLETED', 'CANCELLED', 'VOIDED')
               AND due_time < CURRENT_TIMESTAMP(3)
           )
       ), 0) AS overdue,
       COALESCE(SUM(
           task_status = 'COMPLETED'
           AND DATE(completed_time) = CURRENT_DATE()
       ), 0) AS completed_today
FROM maintenance_task task
WHERE task.tenant_id = #{tenantId}
  AND task.deleted = 0
  AND (
      task.assignee_user_id = #{userId}
      OR EXISTS (
          SELECT 1
          FROM maintenance_task_collaborator collaborator
          WHERE collaborator.tenant_id = task.tenant_id
            AND collaborator.task_id = task.id
            AND collaborator.user_id = #{userId}
      )
  )
